/** কাৰ্ণেল_মান 안의 연결형 বাইট_মান ষ্ট্ৰিম_মান. Ethernet/TCP 패킷 스택이 아닌 루프백 socket তৰপ_মান. */
public final class ষ্ট্ৰিম_নেটৱৰ্ক {
    static int[] অৱস্থা_মান = new int[16], পৰ্ট_মান = new int[16], 짝 = new int[16], পীয়েৰ_পৰ্ট = new int[16], 대기 = new int[16], 묶임 = new int[16];
    static int[] 앞 = new int[16], 수 = new int[16], ডাটা = new int[16 * 1024];
    static int পৰৱৰ্তী_আইটেম = 50000;
    static int প্ৰমাণিত_কৰক(int 열린파일번호) { return 열린파일번호 >= 40 && 열린파일번호 < 56 && অৱস্থা_মান[열린파일번호 - 40] != 0 ? 열린파일번호 - 40 : -1; }
    static boolean 사용중(int 접속번호) { for (int লুপ_ইনডেক্স = 0; লুপ_ইনডেক্স < 16; লুপ_ইনডেক্স++) if (অৱস্থা_মান[লুপ_ইনডেক্স] != 0 && 묶임[লুপ_ইনডেক্স] != 0 && পৰ্ট_মান[লুপ_ইনডেক্স] == 접속번호) return true; return false; }
    public static int ক্ৰিয়েট_প্রবিষ্ট() {
        for (int লুপ_ইনডেক্স = 0; লুপ_ইনডেক্স < 16; লুপ_ইনডেক্স++) if (অৱস্থা_মান[লুপ_ইনডেক্স] == 0) { অৱস্থা_মান[লুপ_ইনডেক্স] = 1; পীয়েৰ_পৰ্ট[লুপ_ইনডেক্স] = পৰ্ট_মান[লুপ_ইনডেক্স] = 앞[লুপ_ইনডেক্স] = 수[লুপ_ইনডেক্স] = 대기[লুপ_ইনডেক্স] = 묶임[লুপ_ইনডেক্স] = 0; 짝[লুপ_ইনডেক্স] = -1; return লুপ_ইনডেক্স + 40; }
        return -24;
    }
    public static int 묶기(int 열린파일번호, int 통신주소, int 접속번호) {
        int লুপ_ইনডেক্স = প্ৰমাণিত_কৰক(열린파일번호); if (লুপ_ইনডেক্স < 0) return -9;
        if (통신주소 != 0 && 통신주소 != 0x7f000001) return -99;
        if (অৱস্থা_মান[লুপ_ইনডেক্স] != 1 || 접속번호 < 0 || 접속번호 > 65535) return -22;
        if (접속번호 == 0) { do { 접속번호 = পৰৱৰ্তী_আইটেম++; if (পৰৱৰ্তী_আইটেম > 65535) পৰৱৰ্তী_আইটেম = 50000; } while (사용중(접속번호)); }
        if (사용중(접속번호)) return -98; পৰ্ট_মান[লুপ_ইনডেক্স] = 접속번호; 묶임[লুপ_ইনডেক্স] = 1; অৱস্থা_মান[লুপ_ইনডেক্স] = 2; return 0;
    }
    public static int 듣기(int 열린파일번호, int 연결대기한도) { int লুপ_ইনডেক্স = প্ৰমাণিত_কৰক(열린파일번호); if (লুপ_ইনডেক্স < 0) return -9; if (অৱস্থা_মান[লুপ_ইনডেক্স] != 2 || 연결대기한도 < 1) return -22; অৱস্থা_মান[লুপ_ইনডেক্স] = 3; return 0; }
    public static int সংযোগ_স্থাপনা(int 열린파일번호, int 통신주소, int 접속번호) {
        int লুপ_ইনডেক্স = প্ৰমাণিত_কৰক(열린파일번호); if (লুপ_ইনডেক্স < 0) return -9; if (통신주소 != 0x7f000001) return -101;
        if (접속번호 < 1 || 접속번호 > 65535 || অৱস্থা_মান[লুপ_ইনডেক্স] > 2) return -22;
        int 수신쪽 = -1; for (int ইনাৰ_যোগদান_স্থান_সলনি_কৰক = 0; ইনাৰ_যোগদান_স্থান_সলনি_কৰক < 16; ইনাৰ_যোগদান_স্থান_সলনি_কৰক++) if (অৱস্থা_মান[ইনাৰ_যোগদান_স্থান_সলনি_কৰক] == 3 && পৰ্ট_মান[ইনাৰ_যোগদান_স্থান_সলনি_কৰক] == 접속번호) 수신쪽 = ইনাৰ_যোগদান_স্থান_সলনি_কৰক;
        if (수신쪽 < 0) return -111;
        int 대기여부 = 0; for (int ইনাৰ_যোগদান_স্থান_সলনি_কৰক = 0; ইনাৰ_যোগদান_স্থান_সলনি_কৰক < 16; ইনাৰ_যোগদান_স্থান_সলনি_কৰক++) if (대기[ইনাৰ_যোগদান_স্থান_সলনি_কৰক] == 수신쪽 + 1) 대기여부++;
        if (대기여부 >= 4) return -11;
        if (অৱস্থা_মান[লুপ_ইনডেক্স] == 1) { int 처리값 = 묶기(열린파일번호, 0x7f000001, 0); if (처리값 < 0) return 처리값; }
        int 다른번호 = ক্ৰিয়েট_প্রবিষ্ট(); if (다른번호 < 0) return 다른번호; 다른번호 -= 40;
        অৱস্থা_মান[লুপ_ইনডেক্স] = অৱস্থা_মান[다른번호] = 4; 짝[লুপ_ইনডেক্স] = 다른번호; 짝[다른번호] = লুপ_ইনডেক্স; পৰ্ট_মান[다른번호] = 접속번호; পীয়েৰ_পৰ্ট[লুপ_ইনডেক্স] = 접속번호; পীয়েৰ_পৰ্ট[다른번호] = পৰ্ট_মান[লুপ_ইনডেক্স]; 대기[다른번호] = 수신쪽 + 1; return 0;
    }
    public static int গ্ৰহণ_সংযোগ(int 열린파일번호) { int লুপ_ইনডেক্স = প্ৰমাণিত_কৰক(열린파일번호); if (লুপ_ইনডেক্স < 0) return -9; if (অৱস্থা_মান[লুপ_ইনডেক্স] != 3) return -22; for (int ইনাৰ_যোগদান_স্থান_সলনি_কৰক = 0; ইনাৰ_যোগদান_স্থান_সলনি_কৰক < 16; ইনাৰ_যোগদান_স্থান_সলনি_কৰক++) if (অৱস্থা_মান[ইনাৰ_যোগদান_স্থান_সলনি_কৰক] != 0 && 대기[ইনাৰ_যোগদান_স্থান_সলনি_কৰক] == লুপ_ইনডেক্স + 1) { 대기[ইনাৰ_যোগদান_স্থান_সলনি_কৰক] = 0; return ইনাৰ_যোগদান_স্থান_সলনি_কৰক + 40; } return -11; }
    public static int লিখা(int 열린파일번호, int 항목수) {
        int লুপ_ইনডেক্স = প্ৰমাণিত_কৰক(열린파일번호); if (লুপ_ইনডেক্স < 0) return -9; if (অৱস্থা_মান[লুপ_ইনডেক্স] != 4) return -107;
        if (항목수 < 0 || 항목수 > 512) return -22; if (항목수 == 0) return 0;
        int ইনাৰ_যোগদান_স্থান_সলনি_কৰক = 짝[লুপ_ইনডেক্স]; if (ইনাৰ_যোগদান_স্থান_সলনি_কৰক < 0) return -32; int 총수 = 1024 - 수[ইনাৰ_যোগদান_স্থান_সলনি_কৰক]; if (총수 == 0) return -11; if (총수 > 항목수) 총수 = 항목수;
        for (int তুলনা_স্থান_সলনি_কৰক = 0; তুলনা_স্থান_সলনি_কৰক < 총수; তুলনা_স্থান_সলনি_কৰক++) ডাটা[ইনাৰ_যোগদান_স্থান_সলনি_কৰক * 1024 + (앞[ইনাৰ_যোগদান_স্থান_সলনি_কৰক] + 수[ইনাৰ_যোগদান_স্থান_সলনি_কৰক] + তুলনা_স্থান_সলনি_কৰক) % 1024] = 되돌림망.অগ্ৰসৰ_মান[তুলনা_স্থান_সলনি_কৰক]; 수[ইনাৰ_যোগদান_স্থান_সলনি_কৰক] += 총수; return 총수;
    }
    public static int পড়া(int 열린파일번호, int 항목수) {
        int লুপ_ইনডেক্স = প্ৰমাণিত_কৰক(열린파일번호); if (লুপ_ইনডেক্স < 0) return -9; if (অৱস্থা_মান[লুপ_ইনডেক্স] != 4) return -107; if (항목수 < 0 || 항목수 > 512) return -22;
        if (항목수 == 0) return 0; if (수[লুপ_ইনডেক্স] == 0) return 짝[লুপ_ইনডেক্স] < 0 ? 0 : -11; if (항목수 > 수[লুপ_ইনডেক্স]) 항목수 = 수[লুপ_ইনডেক্স];
        for (int তুলনা_স্থান_সলনি_কৰক = 0; তুলনা_স্থান_সলনি_কৰক < 항목수; তুলনা_স্থান_সলনি_কৰক++) 되돌림망.অগ্ৰসৰ_মান[তুলনা_স্থান_সলনি_কৰক] = ডাটা[লুপ_ইনডেক্স * 1024 + (앞[লুপ_ইনডেক্স] + তুলনা_স্থান_সলনি_কৰক) % 1024]; 앞[লুপ_ইনডেক্স] = (앞[লুপ_ইনডেক্স] + 항목수) % 1024; 수[লুপ_ইনডেক্স] -= 항목수; return 항목수;
    }
    public static int 창구읽기(int 열린파일번호) { int লুপ_ইনডেক্স = প্ৰমাণিত_কৰক(열린파일번호); return লুপ_ইনডেক্স < 0 ? -9 : পৰ্ট_মান[লুপ_ইনডেক্স]; }
    public static int 상대창구읽기(int 열린파일번호) { int লুপ_ইনডেক্স = প্ৰমাণিত_কৰক(열린파일번호); return লুপ_ইনডেক্স < 0 ? -9 : পীয়েৰ_পৰ্ট[লুপ_ইনডেক্স]; }
    public static int বন্ধ_কৰক(int 열린파일번호) {
        int লুপ_ইনডেক্স = প্ৰমাণিত_কৰক(열린파일번호); if (লুপ_ইনডেক্স < 0) return -9;
        if (অৱস্থা_মান[লুপ_ইনডেক্স] == 3) for (int ইনাৰ_যোগদান_স্থান_সলনি_কৰক = 0; ইনাৰ_যোগদান_স্থান_সলনি_কৰক < 16; ইনাৰ_যোগদান_স্থান_সলনি_কৰক++) if (대기[ইনাৰ_যোগদান_স্থান_সলনি_কৰক] == লুপ_ইনডেক্স + 1) { if (짝[ইনাৰ_যোগদান_স্থান_সলনি_কৰক] >= 0) 짝[짝[ইনাৰ_যোগদান_স্থান_সলনি_কৰক]] = -1; অৱস্থা_মান[ইনাৰ_যোগদান_স্থান_সলনি_কৰক] = 대기[ইনাৰ_যোগদান_স্থান_সলনি_কৰক] = 묶임[ইনাৰ_যোগদান_স্থান_সলনি_কৰক] = 0; }
        if (짝[লুপ_ইনডেক্স] >= 0) 짝[짝[লুপ_ইনডেক্স]] = -1; অৱস্থা_মান[লুপ_ইনডেক্স] = 묶임[লুপ_ইনডেক্স] = 수[লুপ_ইনডেক্স] = 대기[লুপ_ইনডেক্স] = 0; return 0;
    }
}
